def _components(g, bg):
    h, w = len(g), len(g[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            out.append((color, cells))
    return out

def _shape(cells):
    r0 = min(r for r,c in cells); c0 = min(c for r,c in cells)
    return frozenset((r-r0,c-c0) for r,c in cells)

def transform(grid):
    g = [row[:] for row in grid]
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    comps = _components(g, bg)
    # Find congruent components of different colors; recolor the one on the
    # far side of the long corner-shaped marker to the marker's color.
    groups = {}
    for color, cells in comps:
        if len(cells) > 1:
            groups.setdefault(_shape(cells), []).append((color, cells))
    pairs = [v for v in groups.values() if len({c for c,_ in v}) > 1]
    if not pairs:
        return g
    pair = max(pairs, key=lambda v: max(len(cells) for _,cells in v))
    # The long L-shaped guide is the largest component in the grid.
    marker_color, marker = max(comps, key=lambda z: len(z[1]))
    mr0=min(r for r,c in marker); mr1=max(r for r,c in marker)
    mc0=min(c for r,c in marker); mc1=max(c for r,c in marker)
    # Pick the congruent object in the quadrant opposite the guide's arms.
    # For the common right/down guide (corner at upper-left), this is NW.
    candidates=[]
    for color,cells in pair:
        cr=sum(r for r,c in cells)/len(cells); cc=sum(c for r,c in cells)/len(cells)
        score = min(abs(cr-mr0),abs(cr-mr1)) + min(abs(cc-mc0),abs(cc-mc1))
        candidates.append((score,color,cells))
    # In the test layout the matching pair straddles the guide's elbow;
    # the upper-left member is the one to recolor.
    chosen = min(candidates, key=lambda z:(sum(r for r,c in z[2])/len(z[2]), sum(c for r,c in z[2])/len(z[2])))
